];
function countMatches(text, keywords) {
  return keywords.reduce((count, k) => text.includes(k) ? count + 1 : count, 0);
}

const MIN_SCORE = 5;
const results = [];

for (const item of $input.all()) {
  const title = (item.json.title || "").toLowerCase();
  const desc = (item.json.description || "").toLowerCase();
  const link = item.json.link || "";

  let score = 0;


  score += countMatches(desc, JOB_KEYWORDS) * 5;
  score += countMatches(desc, BUILD_KEYWORDS) * 3;
  score += countMatches(desc, PAIN_KEYWORDS) * 2;


  if (desc.includes("script") || desc.includes("api")) score += 2;
  if (desc.includes("tool") || desc.includes("workflow")) score += 2;


  score -= countMatches(title, BAD_KEYWORDS) * 4;
  score -= countMatches(desc, BAD_KEYWORDS) * 3;


  if (desc.length > 120) score += 1;
  if (link.includes("/r/")) score += 1;

  if (score >= MIN_SCORE) {
    results.push({
      json: {
        subreddit: item.json.subreddit,
        link,
        score,
        category:
          score >= 10 ? "🔥 High-value" :
          score >= 7 ? "✅ Good" :
          "⚠️ Medium"
      }
    });
  }
}

return results;

const now = new Date();
const results = [];

for (const item of $input.all()) {
  const score = item.json.score || 0;
  const category = item.json.category || "";
  const prevFirstSeen = item.json.first_seen;
  const prevLastSeen = item.json.last_seen;


  const firstSeen = prevFirstSeen
    ? new Date(prevFirstSeen)
    : now;

  const lastSeenPrev = prevLastSeen
    ? new Date(prevLastSeen)
    : now;

  const daysSinceLastSeen = Math.floor(
    (now - lastSeenPrev) / (1000 * 60 * 60 * 24)
  );

  const weeksAlive = Math.max(
    1,
    Math.floor((now - firstSeen) / (1000 * 60 * 60 * 24 * 7))
  );

  let confidence = score * 10;

  confidence += Math.min(weeksAlive * 5, 30);

  if (category.includes("High")) confidence += 20;
  else if (category.includes("Good")) confidence += 10;

  if (daysSinceLastSeen > 60) confidence = 0;
  else if (daysSinceLastSeen > 30) confidence -= 30;
  else if (daysSinceLastSeen > 7) confidence -= 10;

  confidence = Math.max(0, Math.min(100, confidence));

  let status = "Candidate";
  let action = "Monitored";

  if (confidence >= 90) {
    status = "Evergreen";
    action = "Always scanned";
  } else if (confidence >= 70) {
    status = "Validated";
    action = "Scanned";
  } else if (confidence >= 30) {
    status = "Candidate";
    action = "Monitored";
  } else {
    status = "Archived";
    action = "Ignored";
  }

  results.push({
    json: {
      subreddit: item.json.subreddit,
      link: item.json.link,
      score,
      category,
      confidence,
      status,
      action,
      first_seen: firstSeen.toISOString(),
      last_seen: now.toISOString()
    }
  });
}

return results;

