/* ---------- helpers ---------- */
function extract(entry, regex) {
  const m = entry.match(regex);
  return m ? m[1].trim() : "";
}

function decodeEntities(text = "") {
  return text
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#32;/g, " ")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

function cleanText(raw = "") {
  return decodeEntities(raw)
    .replace(/<img[\s\S]*?>/gi, "")
    .replace(/<a[^>]*>(.*?)<\/a>/gi, "$1")
    .replace(/<[^>]+>/g, "")
    .replace(/\[comments\]/gi, "")
    .replace(/submitted by[\s\S]*$/gi, "")
    .replace(/\s+/g, " ")
    .trim();
}

function extractBody(entry) {
  let body = extract(entry, /<div class="md">([\s\S]*?)<\/div>/);

  if (!body) {
    body = extract(entry, /<content[^>]*>([\s\S]*?)<\/content>/);
  }

  return cleanText(body);
}


/* ---------- main ---------- */
