const results = [];

for (const item of $input.all()) {

  const text = (
    (item.json.text || "") +
    " " +
    (item.json.title || "")
  ).toLowerCase();

  // 1️⃣ HARD KILL — never jobs
  if (hasAny(text, HARD_NEGATIVE_PATTERNS)) continue;

  // 2️⃣ Reject freelancer self-promo
  if (hasAny(text, NEGATIVE_KEYWORDS)) continue;

  // 3️⃣ Must show employer intent
  if (!hasAny(text, EMPLOYER_INTENT)) continue;

  let score = 0;

  // Employer intent is KING
  score += count(text, EMPLOYER_INTENT) * 40;

  // Payment evidence
  score += count(text, MONEY_KEYWORDS) * 25;

  // Skill relevance
  score += count(text, SKILL_KEYWORDS) * 8;

  // Length bonus (real job posts are detailed)
  if (text.length > 400) score += 10;
  if (text.length > 800) score += 10;

  // 4️⃣ Classification
  if (score < 25) continue; // noise

  let action = "notion";
  if (score >= 120) action = "telegram";

  results.push({
    json: {
      subreddit: item.json.subreddit || "",
      title: item.json.title || "",
      link: item.json.link || "",
      published: item.json.published || "",
      job_score: score,
      intent: "job",
      action
    }
  });
}

return results;

