  .map((item, index) => {
    try {
      const parsed = JSON.parse(item.json.output);

      return {
        json: {
          id: index + 1,
          is_job: Boolean(parsed.is_job),
          confidence: Number(parsed.confidence ?? 0),
          reason: parsed.reason?.trim() || "",
          link: parsed.link?.trim() || null
        }
